 * @param {*} t 数组，元素表示每个士兵的过河时长
 * @return {*} ”最多存活士兵数” “最短用时”
 */
function getResult(n, limit, t) {
  // 过河时间升序
  t.sort((a, b) => a - b);

  const dp = new Array(n);

  for (let i = 0; i < n; i++) {
    if (i == 0) {
      dp[0] = t[0];
      if (dp[0] > limit) return "0 0";
    } else if (i == 1) {
      dp[1] = t[1];
    } else {
      dp[i] = Math.min(
        dp[i - 1] + t[i] + t[0],
        dp[i - 2] + t[0] + t[i] + t[1] + t[1]
      );
    }

    if (dp[i] > limit) return i + " " + dp[i - 1];
  }

  return n + " " + dp[n - 1];
}

